inbound.set-body:
@{
        int window;
        if (!int.TryParse(context.Request.Url.Query.GetValueOrDefault("window_minutes", "60"), out window)) { window = 60; }
        return new JObject(
            new JProperty("service_id", context.Request.Url.Query.GetValueOrDefault("service_id", "")),
            new JProperty("window_minutes", Math.Max(5, Math.Min(window, 1440)))
        ).ToString();
    }
